summary:
bash: # Let's trace the first contig from ATAGCCAGTGCCTGATACT (FG)
# F = no left, G = right extension is G
# So contig starts with ATAGCCAGTGCCTGATACT, then extends with G
# Next kmer = TAGCCAGTGCCTGATACTG (shift left by 1, add G)
# Let's verify this chain
awk -F'\t' '
BEGIN { kmer="ATAGCCAGTGCCTGATACT"; contig=kmer; }
{
  if ($1 == kmer) {
    left = substr($2,1,1);
    right = substr($2,2,1);
    printf "kmer=%s left=%s right=%s\n", kmer, left, right;
    if (right != "F") {
      contig = contig right;
      kmer = substr(kmer, 2) right;
    } else {
      printf "END\n";
      break;
    }
  }
}
END { printf "Contig: %s\n", contig; }
' /app/test

